-- ============================================================================
-- C-SHOPPER US Costco warehouse seed — 605 warehouses, 49 states + PR.
-- Source: jessicaengel451/costco-roadtrip (public GitHub, "all US Costco
--   locations", refreshed ~Sep 2026) joined with its coordinates file.
-- Coverage: 602/605 coords from the source; 3 filled via zippopotam.us
--   (Springdale OH, zip centroid) and Nominatim/OSM (Bayamon PR address,
--   Caguas PR city-level — approximate, flagged in build notes).
-- RUN AFTER supabase/schema.sql (and after migration_002_location.sql on the
-- live DB). Replaces the 3 placeholder test warehouses.
-- IDs are stable text keys: us-<state>-NNNN (e.g. us-ca-0001).
-- ============================================================================

-- Remove the 3 placeholder test warehouses (no real user data exists yet).
delete from stores where id in ('1','2','3');

on conflict (id) do update set name=excluded.name, address=excluded.address, zip_code=excluded.zip_code, latitude=excluded.latitude, longitude=excluded.longitude, phone=excluded.phone;
